import axios from 'axios';

// Configure axios with base URL
const API_BASE_URL = 'http://127.0.0.1:8000';

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 30000, // 30 seconds timeout
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor for logging
api.interceptors.request.use(
  (config) => {
    console.log(`Making ${config.method?.toUpperCase()} request to ${config.url}`);
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor for error handling
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    console.error('API Error:', error.response?.data || error.message);
    return Promise.reject(error);
  }
);

// API functions
export const uploadLogs = async (loginLogsFile, fileAccessLogsFile) => {
  const formData = new FormData();
  formData.append('login_logs', loginLogsFile);
  formData.append('file_access_logs', fileAccessLogsFile);
  
  const response = await api.post('/upload/', formData, {
    headers: {
      'Content-Type': 'multipart/form-data',
    },
  });
  return response.data;
};

export const runDetectionPipeline = async () => {
  const response = await api.post('/process/');
  return response.data;
};

export const getBreachEvents = async () => {
  const response = await fetch('http://127.0.0.1:8000/breach-events/');
  if (!response.ok) {
    throw new Error(`Failed to fetch breach events: ${response.status}`);
  }
  return response.json();
};

export const registerFileForMonitoring = async (filePath) => {
  const response = await fetch('http://127.0.0.1:8000/register-file/', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ file_path: filePath }),
  });
  if (!response.ok) {
    throw new Error(`Failed to register file: ${response.status}`);
  }
  return response.json();
};

export const checkFileTampering = async () => {
  const response = await fetch('http://127.0.0.1:8000/tamper-check/');
  if (!response.ok) {
    throw new Error(`Failed to check tampering: ${response.status}`);
  }
  return response.json();
};

// New download functions
export const downloadBreachEventsCSV = async () => {
  const response = await fetch('http://127.0.0.1:8000/data/correlated_breach_events.csv');
  if (!response.ok) {
    throw new Error(`Failed to download breach events: ${response.status}`);
  }
  return response.blob();
};

export const downloadTamperedFilesCSV = async () => {
  const response = await fetch('http://127.0.0.1:8000/data/tampered_files.csv');
  if (!response.ok) {
    throw new Error(`Failed to download tampered files: ${response.status}`);
  }
  return response.blob();
};

export default api;
